/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #131722;
  --bg-card: #1e222d;
  --bg-card-hover: #252a36;
  --bg-input: #1e222d;
  --bg-nav: #0F0F0F;
  --accent: #2962FF;
  --accent-hover: #1e53e5;
  --accent-light: rgba(41, 98, 255, 0.12);
  --red: #F7525F;
  --red-bg: rgba(247, 82, 95, 0.1);
  --green: #26a69a;
  --green-bg: rgba(38, 166, 154, 0.1);
  --yellow: #ff9800;
  --yellow-bg: rgba(255, 152, 0, 0.1);
  --text-primary: #d1d4dc;
  --text-secondary: #787b86;
  --text-muted: #555862;
  --border: #2a2e39;
  --border-light: #363a45;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.4);
  --radius: 6px;
  --radius-lg: 10px;
  --nav-height: 56px;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--accent); text-decoration: none; transition: color 0.15s; }
a:hover { color: var(--accent-hover); }

img { max-width: 100%; display: block; }

button { font-family: var(--font); cursor: pointer; border: none; background: none; color: var(--text-primary); }

/* ─── Navigation ─── */
.nav {
  position: sticky; top: 0; z-index: 100;
  height: var(--nav-height);
  background: var(--bg-nav);
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center;
  padding: 0 24px;
}
.nav__brand {
  display: flex; align-items: center; gap: 8px;
  font-weight: 700; font-size: 1.25rem; color: #fff;
  margin-right: 32px; white-space: nowrap;
}
.nav__brand svg { width: 28px; height: 28px; }
.nav__links {
  display: flex; gap: 4px; list-style: none; flex: 1;
}
.nav__links a {
  padding: 8px 14px; border-radius: var(--radius);
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  transition: all 0.15s; white-space: nowrap;
}
.nav__links a:hover, .nav__links a.active {
  color: var(--text-primary); background: var(--accent-light);
}
.nav__links a.active { color: var(--accent); }
.nav__right {
  display: flex; align-items: center; gap: 12px; margin-left: auto;
}
.nav__search {
  display: flex; align-items: center; gap: 6px;
  background: var(--bg-input); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 6px 12px; color: var(--text-secondary);
  font-size: 0.85rem; cursor: pointer;
}
.nav__btn {
  padding: 7px 18px; border-radius: var(--radius); font-weight: 600;
  font-size: 0.85rem; transition: all 0.15s;
}
.nav__btn--outline { border: 1px solid var(--border); color: var(--text-primary); }
.nav__btn--outline:hover { border-color: var(--accent); color: var(--accent); }
.nav__btn--primary { background: var(--accent); color: #fff; }
.nav__btn--primary:hover { background: var(--accent-hover); }

/* ─── Container ─── */
.container { max-width: 1320px; margin: 0 auto; padding: 0 24px; }

/* ─── Hero ─── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; top: -120px; left: 50%; transform: translateX(-50%);
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(41,98,255,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero h1 {
  font-size: 3rem; font-weight: 800; line-height: 1.15;
  max-width: 720px; margin: 0 auto 16px; color: #fff;
}
.hero h1 span { color: var(--accent); }
.hero p {
  font-size: 1.15rem; color: var(--text-secondary);
  max-width: 560px; margin: 0 auto 32px; line-height: 1.6;
}
.hero__actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 12px 28px; border-radius: var(--radius); font-weight: 600;
  font-size: 0.95rem; transition: all 0.15s; cursor: pointer; border: none;
}
.btn--primary { background: var(--accent); color: #fff; }
.btn--primary:hover { background: var(--accent-hover); transform: translateY(-1px); }
.btn--ghost { background: transparent; color: var(--text-primary); border: 1px solid var(--border); }
.btn--ghost:hover { border-color: var(--accent); color: var(--accent); }

/* ─── Section ─── */
.section { padding: 48px 0; }
.section__header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px; flex-wrap: wrap; gap: 12px;
}
.section__title {
  font-size: 1.25rem; font-weight: 700; color: #fff;
}

/* ─── Tabs ─── */
.tabs {
  display: flex; gap: 2px; background: var(--bg-card);
  border-radius: var(--radius); padding: 3px; overflow-x: auto;
}
.tab {
  padding: 7px 16px; border-radius: 4px; font-size: 0.85rem;
  font-weight: 500; color: var(--text-secondary);
  transition: all 0.15s; white-space: nowrap; cursor: pointer;
}
.tab:hover { color: var(--text-primary); }
.tab.active {
  background: var(--accent); color: #fff; font-weight: 600;
}
.tabs--pills { background: transparent; gap: 4px; padding: 0; }
.tabs--pills .tab { padding: 6px 14px; border-radius: 20px; }
.tabs--pills .tab.active { background: var(--accent-light); color: var(--accent); }

/* ─── Market Summary Bar ─── */
.market-bar {
  display: flex; gap: 2px; padding: 12px 0;
  overflow-x: auto; scrollbar-width: none;
}
.market-bar::-webkit-scrollbar { display: none; }
.market-bar__item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 16px; background: var(--bg-card);
  border-radius: var(--radius); white-space: nowrap; min-width: fit-content;
}
.market-bar__name { font-weight: 600; font-size: 0.85rem; color: var(--text-primary); }
.market-bar__price { font-size: 0.85rem; color: var(--text-primary); }
.market-bar__change { font-size: 0.8rem; font-weight: 600; }
.market-bar__change.positive { color: var(--green); }
.market-bar__change.negative { color: var(--red); }

/* ─── Cards ─── */
.card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.card:hover { border-color: var(--border-light); box-shadow: var(--shadow); }
.card__header {
  padding: 14px 16px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}
.card__title { font-size: 0.9rem; font-weight: 600; color: #fff; }
.card__body { padding: 16px; }

/* ─── Grid ─── */
.grid { display: grid; gap: 16px; }
.grid--2 { grid-template-columns: repeat(2, 1fr); }
.grid--3 { grid-template-columns: repeat(3, 1fr); }
.grid--4 { grid-template-columns: repeat(4, 1fr); }

/* ─── Stock Row ─── */
.stock-row {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 0; border-bottom: 1px solid var(--border);
}
.stock-row:last-child { border-bottom: none; }
.stock-row__ticker {
  font-weight: 700; font-size: 0.9rem; color: var(--accent);
  min-width: 50px;
}
.stock-row__name {
  flex: 1; font-size: 0.85rem; color: var(--text-secondary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.stock-row__sparkline { width: 80px; height: 32px; }
.stock-row__price { font-weight: 600; font-size: 0.9rem; text-align: right; min-width: 70px; }
.stock-row__change {
  font-weight: 600; font-size: 0.8rem; text-align: right; min-width: 60px;
  padding: 3px 8px; border-radius: 4px;
}
.stock-row__change.positive { color: var(--green); background: var(--green-bg); }
.stock-row__change.negative { color: var(--red); background: var(--red-bg); }

/* ─── Data Table ─── */
.data-table { width: 100%; border-collapse: collapse; }
.data-table th {
  padding: 10px 12px; font-size: 0.75rem; font-weight: 600;
  color: var(--text-secondary); text-align: left;
  border-bottom: 1px solid var(--border); text-transform: uppercase;
  letter-spacing: 0.5px;
}
.data-table td {
  padding: 10px 12px; font-size: 0.85rem;
  border-bottom: 1px solid var(--border);
}
.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover td { background: var(--bg-card-hover); }
.data-table .positive { color: var(--green); }
.data-table .negative { color: var(--red); }
.data-table .ticker { color: var(--accent); font-weight: 600; }

/* ─── Badge ─── */
.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 10px; border-radius: 20px; font-size: 0.75rem;
  font-weight: 600;
}
.badge--green { background: var(--green-bg); color: var(--green); }
.badge--red { background: var(--red-bg); color: var(--red); }
.badge--blue { background: var(--accent-light); color: var(--accent); }
.badge--yellow { background: var(--yellow-bg); color: var(--yellow); }
.badge--platinum { background: linear-gradient(135deg, #e5e4e2, #b0afad); color: #1a1a2e; }
.badge--gold { background: linear-gradient(135deg, #ffd700, #daa520); color: #1a1a2e; }

/* ─── Star Rating ─── */
.stars { color: var(--yellow); font-size: 0.85rem; letter-spacing: 1px; }

/* ─── Trending Stocks ─── */
.trending-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 10px;
}
.trending-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 14px; background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius); transition: all 0.15s; cursor: pointer;
}
.trending-item:hover { border-color: var(--accent); background: var(--bg-card-hover); }
.trending-item__ticker { font-weight: 700; font-size: 0.9rem; color: var(--accent); }
.trending-item__price { font-size: 0.8rem; color: var(--text-secondary); margin-top: 2px; }
.trending-item__change { font-weight: 600; font-size: 0.8rem; }
.trending-item__change.positive { color: var(--green); }
.trending-item__change.negative { color: var(--red); }

/* ─── Idea Card ─── */
.idea-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: border-color 0.15s;
}
.idea-card:hover { border-color: var(--border-light); }
.idea-card__image {
  height: 180px; background: var(--bg-secondary);
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.idea-card__chart {
  width: 100%; height: 100%;
}
.idea-card__avatar {
  width: 28px; height: 28px; border-radius: 50%;
  background: var(--accent); display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; font-weight: 700; color: #fff;
}
.idea-card__content { padding: 14px 16px; }
.idea-card__author {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 8px;
}
.idea-card__author-name { font-size: 0.8rem; font-weight: 600; color: var(--text-primary); }
.idea-card__author-time { font-size: 0.75rem; color: var(--text-muted); }
.idea-card__title { font-size: 0.95rem; font-weight: 600; color: #fff; line-height: 1.4; margin-bottom: 8px; }
.idea-card__tags { display: flex; gap: 6px; flex-wrap: wrap; }
.idea-card__tag {
  font-size: 0.7rem; padding: 2px 8px; border-radius: 4px;
  background: var(--accent-light); color: var(--accent); font-weight: 500;
}
.idea-card__stats {
  display: flex; gap: 16px; padding: 10px 16px;
  border-top: 1px solid var(--border); font-size: 0.75rem; color: var(--text-secondary);
}
.idea-card__stat { display: flex; align-items: center; gap: 4px; }

/* ─── Footer ─── */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 48px 0 24px; margin-top: 48px;
}
.footer__grid {
  display: grid; grid-template-columns: repeat(6, 1fr);
  gap: 32px; margin-bottom: 32px;
}
.footer__col-title {
  font-size: 0.85rem; font-weight: 700; color: #fff;
  margin-bottom: 12px;
}
.footer__col-links {
  list-style: none; display: flex; flex-direction: column; gap: 8px;
}
.footer__col-links a {
  font-size: 0.8rem; color: var(--text-secondary);
}
.footer__col-links a:hover { color: var(--accent); }
.footer__bottom {
  border-top: 1px solid var(--border); padding-top: 20px;
  display: flex; align-items: center; justify-content: space-between;
  font-size: 0.8rem; color: var(--text-muted);
}
.footer__brand { font-weight: 700; color: #fff; font-size: 1.1rem; }

/* ═══════════════════════════════════════════
   CHART PAGE
   ═══════════════════════════════════════════ */
.chart-workspace {
  display: grid;
  grid-template-columns: 240px 1fr 320px;
  grid-template-rows: auto 1fr;
  height: calc(100vh - var(--nav-height));
  overflow: hidden;
}
.chart-toolbar {
  grid-column: 1 / -1;
  display: flex; align-items: center; gap: 6px;
  padding: 6px 12px; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  overflow-x: auto; scrollbar-width: none;
}
.chart-toolbar::-webkit-scrollbar { display: none; }
.toolbar-group {
  display: flex; gap: 2px; padding-right: 12px;
  border-right: 1px solid var(--border); margin-right: 6px;
}
.toolbar-group:last-child { border-right: none; }
.toolbar-btn {
  padding: 5px 10px; border-radius: 4px; font-size: 0.78rem;
  font-weight: 500; color: var(--text-secondary);
  transition: all 0.1s; white-space: nowrap;
}
.toolbar-btn:hover { color: var(--text-primary); background: var(--bg-card); }
.toolbar-btn.active { color: var(--accent); background: var(--accent-light); }

/* Watchlist */
.watchlist {
  grid-column: 1;
  grid-row: 2;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.watchlist__header {
  padding: 10px 14px; font-weight: 700; font-size: 0.85rem; color: #fff;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
}
.watchlist__category {
  border-bottom: 1px solid var(--border);
}
.watchlist__category-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 14px; cursor: pointer; user-select: none;
  font-weight: 600; font-size: 0.8rem; color: var(--text-secondary);
  transition: background 0.1s;
}
.watchlist__category-header:hover { background: var(--bg-card); }
.watchlist__category-header .arrow {
  transition: transform 0.2s; font-size: 0.7rem;
}
.watchlist__category-header.collapsed .arrow { transform: rotate(-90deg); }
.watchlist__category-items { padding: 0; }
.watchlist__category-items.collapsed { display: none; }
.watchlist__item {
  display: grid; grid-template-columns: 1fr auto auto;
  gap: 8px; padding: 6px 14px; cursor: pointer;
  transition: background 0.1s; font-size: 0.8rem;
}
.watchlist__item:hover { background: var(--bg-card-hover); }
.watchlist__item.active { background: var(--accent-light); }
.watchlist__symbol { font-weight: 600; color: var(--text-primary); }
.watchlist__last { text-align: right; color: var(--text-primary); }
.watchlist__chg { text-align: right; font-weight: 600; }
.watchlist__chg.positive { color: var(--green); }
.watchlist__chg.negative { color: var(--red); }

/* Chart area */
.chart-area {
  grid-column: 2; grid-row: 2;
  position: relative; background: #131722;
  overflow: hidden;
}
.chart-area canvas { width: 100%; height: 100%; display: block; }
.chart-area__overlay {
  position: absolute; top: 12px; left: 12px;
  display: flex; flex-direction: column; gap: 4px;
}
.chart-ticker {
  font-size: 1.1rem; font-weight: 700; color: #fff;
}
.chart-price {
  font-size: 1.6rem; font-weight: 700; color: var(--red);
}
.chart-change {
  font-size: 0.85rem; font-weight: 600; color: var(--red);
}
.chart-timeframes {
  position: absolute; top: 12px; right: 12px;
  display: flex; gap: 2px; background: rgba(19,23,34,0.85);
  padding: 3px; border-radius: var(--radius);
}
.tf-btn {
  padding: 4px 10px; border-radius: 3px; font-size: 0.75rem;
  font-weight: 600; color: var(--text-secondary); transition: all 0.1s;
}
.tf-btn:hover { color: var(--text-primary); }
.tf-btn.active { background: var(--accent); color: #fff; }

/* Detail panel */
.detail-panel {
  grid-column: 3; grid-row: 2;
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  overflow-y: auto;
}
.detail-panel__header {
  padding: 14px 16px; border-bottom: 1px solid var(--border);
}
.detail-panel__ticker {
  font-size: 1.2rem; font-weight: 800; color: #fff;
}
.detail-panel__company { font-size: 0.8rem; color: var(--text-secondary); margin-top: 2px; }
.detail-panel__exchange {
  font-size: 0.7rem; color: var(--text-muted); margin-top: 2px;
}
.detail-panel__price-section {
  padding: 12px 16px; border-bottom: 1px solid var(--border);
}
.detail-panel__price { font-size: 1.8rem; font-weight: 700; color: var(--red); }
.detail-panel__change {
  font-size: 0.9rem; font-weight: 600; color: var(--red); margin-top: 2px;
}
.detail-panel__stat-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 1px; padding: 0 16px;
}
.detail-panel__stat {
  padding: 10px 0; border-bottom: 1px solid var(--border);
}
.detail-panel__stat-label {
  font-size: 0.7rem; color: var(--text-muted); text-transform: uppercase;
  letter-spacing: 0.3px; margin-bottom: 2px;
}
.detail-panel__stat-value { font-size: 0.85rem; font-weight: 600; color: var(--text-primary); }
.detail-panel__section {
  padding: 14px 16px; border-bottom: 1px solid var(--border);
}
.detail-panel__section-title {
  font-size: 0.8rem; font-weight: 700; color: #fff;
  margin-bottom: 10px;
}
.detail-panel__headline {
  font-size: 0.8rem; color: var(--text-secondary);
  line-height: 1.5; padding: 10px 16px;
  border-bottom: 1px solid var(--border);
}
.financial-row {
  display: flex; justify-content: space-between; align-items: center;
  padding: 6px 0; font-size: 0.8rem;
}
.financial-row__label { color: var(--text-secondary); }
.financial-row__value { font-weight: 600; color: var(--text-primary); }
.financial-row__value.positive { color: var(--green); }
.financial-row__value.negative { color: var(--red); }

/* Detail panel tabs */
.detail-tabs {
  display: flex; border-bottom: 1px solid var(--border);
}
.detail-tab {
  flex: 1; padding: 10px; text-align: center;
  font-size: 0.78rem; font-weight: 600; color: var(--text-secondary);
  border-bottom: 2px solid transparent; transition: all 0.15s;
}
.detail-tab:hover { color: var(--text-primary); }
.detail-tab.active { color: var(--accent); border-bottom-color: var(--accent); }

/* ═══════════════════════════════════════════
   IDEAS PAGE
   ═══════════════════════════════════════════ */
.ideas-header {
  padding: 32px 0 16px;
}
.ideas-header h1 {
  font-size: 1.8rem; font-weight: 800; color: #fff; margin-bottom: 8px;
}
.ideas-header p { color: var(--text-secondary); font-size: 1rem; }
.ideas-filters {
  display: flex; align-items: center; gap: 16px;
  padding: 16px 0; flex-wrap: wrap;
}
.filter-toggle {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 14px; border-radius: 20px;
  background: var(--bg-card); border: 1px solid var(--border);
  font-size: 0.8rem; color: var(--text-secondary);
  transition: all 0.15s; cursor: pointer;
}
.filter-toggle:hover { border-color: var(--accent); color: var(--accent); }
.filter-toggle.active { background: var(--accent-light); border-color: var(--accent); color: var(--accent); }
.filter-toggle__check {
  width: 16px; height: 16px; border-radius: 3px;
  border: 1.5px solid var(--text-muted); display: flex;
  align-items: center; justify-content: center;
  font-size: 0.65rem; transition: all 0.15s;
}
.filter-toggle.active .filter-toggle__check {
  background: var(--accent); border-color: var(--accent); color: #fff;
}
.ideas-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px;
}
.pagination {
  display: flex; justify-content: center; gap: 6px;
  padding: 32px 0;
}
.pagination__btn {
  padding: 8px 14px; border-radius: var(--radius);
  font-size: 0.85rem; font-weight: 500;
  color: var(--text-secondary); border: 1px solid var(--border);
  transition: all 0.15s;
}
.pagination__btn:hover { border-color: var(--accent); color: var(--accent); }
.pagination__btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }

/* ═══════════════════════════════════════════
   MARKETS PAGE
   ═══════════════════════════════════════════ */
.markets-tabs {
  display: flex; gap: 4px; padding: 16px 0;
  overflow-x: auto; scrollbar-width: none;
}
.markets-tabs::-webkit-scrollbar { display: none; }
.markets-tab {
  padding: 10px 20px; border-radius: var(--radius);
  font-size: 0.9rem; font-weight: 600;
  color: var(--text-secondary); background: var(--bg-card);
  transition: all 0.15s; white-space: nowrap; cursor: pointer;
}
.markets-tab:hover { color: var(--text-primary); }
.markets-tab.active { background: var(--accent); color: #fff; }

.market-section { padding: 24px 0; }
.market-section__header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 16px;
}
.market-section__title {
  font-size: 1.2rem; font-weight: 700; color: #fff;
}
.market-section__controls {
  display: flex; gap: 2px;
}
.chart-option {
  padding: 4px 10px; font-size: 0.75rem; font-weight: 500;
  color: var(--text-muted); border-radius: 3px; transition: all 0.1s;
}
.chart-option:hover { color: var(--text-secondary); }
.chart-option.active { color: var(--accent); background: var(--accent-light); }

.mini-chart { width: 100%; height: 40px; }

.movers-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.mover-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 16px;
}
.mover-card__title {
  font-size: 0.85rem; font-weight: 700; color: #fff; margin-bottom: 12px;
}
.mover-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 0; border-bottom: 1px solid var(--border);
}
.mover-item:last-child { border-bottom: none; }
.mover-item__name { font-size: 0.85rem; color: var(--text-primary); }
.mover-item__change { font-weight: 700; font-size: 0.85rem; }
.mover-item__change.positive { color: var(--green); }
.mover-item__change.negative { color: var(--red); }

.earnings-table-wrap { overflow-x: auto; }

/* ═══════════════════════════════════════════
   BROKERS PAGE
   ═══════════════════════════════════════════ */
.brokers-hero {
  padding: 60px 0 40px; text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.brokers-hero h1 { font-size: 2.2rem; font-weight: 800; color: #fff; margin-bottom: 8px; }
.brokers-hero p { color: var(--text-secondary); font-size: 1.05rem; max-width: 520px; margin: 0 auto; }

.broker-filters {
  display: flex; align-items: center; gap: 16px;
  padding: 20px 0; flex-wrap: wrap;
}
.broker-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  display: grid; grid-template-columns: auto 1fr auto;
  gap: 20px; align-items: center;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.broker-card:hover { border-color: var(--border-light); box-shadow: var(--shadow); }
.broker-card__logo {
  width: 56px; height: 56px; border-radius: var(--radius);
  background: var(--bg-secondary); display: flex;
  align-items: center; justify-content: center;
  font-weight: 800; font-size: 0.8rem; color: var(--accent);
  border: 1px solid var(--border);
}
.broker-card__info { min-width: 0; }
.broker-card__name { font-size: 1rem; font-weight: 700; color: #fff; }
.broker-card__meta {
  display: flex; align-items: center; gap: 10px;
  margin-top: 6px; flex-wrap: wrap;
}
.broker-card__rating {
  display: flex; align-items: center; gap: 4px;
  font-size: 0.85rem; font-weight: 600;
}
.broker-card__stat {
  font-size: 0.8rem; color: var(--text-secondary);
}
.broker-card__promo {
  font-size: 0.8rem; color: var(--green); font-weight: 500;
  margin-top: 6px;
}
.broker-card__action { text-align: right; white-space: nowrap; }
.broker-card__cta {
  padding: 10px 24px; background: var(--accent); color: #fff;
  border-radius: var(--radius); font-weight: 600; font-size: 0.85rem;
  transition: background 0.15s; border: none; cursor: pointer;
}
.broker-card__cta:hover { background: var(--accent-hover); }

.stats-banner {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 40px;
  display: flex; justify-content: center; gap: 80px;
  margin-top: 32px; text-align: center;
}
.stats-banner__item {}
.stats-banner__value { font-size: 2.4rem; font-weight: 800; color: #fff; }
.stats-banner__label { font-size: 0.85rem; color: var(--text-secondary); margin-top: 4px; }

/* ─── Pre-market badge ─── */
.pre-market {
  display: flex; align-items: center; gap: 6px;
  padding: 8px 16px; background: var(--bg-card);
  border-radius: var(--radius); margin-top: 8px;
}
.pre-market__label { font-size: 0.7rem; font-weight: 600; color: var(--yellow); text-transform: uppercase; }
.pre-market__price { font-size: 0.85rem; font-weight: 600; color: var(--green); }

/* ─── Accordion ─── */
.accordion-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 0; cursor: pointer; user-select: none;
}
.accordion-header .arrow { transition: transform 0.2s; font-size: 0.7rem; }
.accordion-header.collapsed .arrow { transform: rotate(-90deg); }
.accordion-body { overflow: hidden; transition: max-height 0.3s; }
.accordion-body.collapsed { max-height: 0 !important; }

/* ─── Responsive ─── */
@media (max-width: 1200px) {
  .chart-workspace { grid-template-columns: 200px 1fr 280px; }
}
@media (max-width: 1024px) {
  .chart-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    height: auto;
  }
  .chart-area { min-height: 400px; }
  .watchlist { border-right: none; border-bottom: 1px solid var(--border); max-height: 200px; }
  .detail-panel { border-left: none; border-top: 1px solid var(--border); }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .grid--4 { grid-template-columns: repeat(2, 1fr); }
  .broker-card { grid-template-columns: 1fr; }
  .broker-card__action { text-align: left; }
}
@media (max-width: 768px) {
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .nav__links { display: none; }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .grid--3, .grid--2 { grid-template-columns: 1fr; }
  .movers-grid { grid-template-columns: 1fr; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .chart-workspace { grid-template-columns: 1fr; }
  .ideas-grid { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .footer__grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 1.6rem; }
  .trending-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ─── Utility ─── */
.text-positive { color: var(--green) !important; }
.text-negative { color: var(--red) !important; }
.text-muted { color: var(--text-muted) !important; }
.text-accent { color: var(--accent) !important; }
.text-right { text-align: right; }
.text-center { text-align: center; }
.font-bold { font-weight: 700; }
.mt-0 { margin-top: 0; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.gap-8 { gap: 8px; }
.gap-16 { gap: 16px; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.flex-wrap { flex-wrap: wrap; }
.hidden { display: none !important; }

/* Tab content switching */
.tab-content { display: none; }
.tab-content.active { display: block; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--border-light); }

