605	  background: var(--bg-card); border: 1px solid var(--border);
606	  border-radius: var(--radius-lg); padding: 16px;
607	}
608	.mover-card__title {
609	  font-size: 0.85rem; font-weight: 700; color: #fff; margin-bottom: 12px;
610	}
611	.mover-item {
612	  display: flex; align-items: center; justify-content: space-between;
613	  padding: 8px 0; border-bottom: 1px solid var(--border);
614	}
615	.mover-item:last-child { border-bottom: none; }
616	.mover-item__name { font-size: 0.85rem; color: var(--text-primary); }
617	.mover-item__change { font-weight: 700; font-size: 0.85rem; }
618	.mover-item__change.positive { color: var(--green); }
619	.mover-item__change.negative { color: var(--red); }
620	
621	.earnings-table-wrap { overflow-x: auto; }
622	
623	/* ═══════════════════════════════════════════
624	   BROKERS PAGE
625	   ═══════════════════════════════════════════ */
626	.brokers-hero {
627	  padding: 60px 0 40px; text-align: center;
628	  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
629	}
630	.brokers-hero h1 { font-size: 2.2rem; font-weight: 800; color: #fff; margin-bottom: 8px; }
631	.brokers-hero p { color: var(--text-secondary); font-size: 1.05rem; max-width: 520px; margin: 0 auto; }
632	
633	.broker-filters {
634	  display: flex; align-items: center; gap: 16px;
635	  padding: 20px 0; flex-wrap: wrap;
636	}
637	.broker-card {
638	  background: var(--bg-card); border: 1px solid var(--border);
639	  border-radius: var(--radius-lg); padding: 20px;
640	  display: grid; grid-template-columns: auto 1fr auto;
641	  gap: 20px; align-items: center;
642	  transition: border-color 0.15s, box-shadow 0.15s;
643	}
644	.broker-card:hover { border-color: var(--border-light); box-shadow: var(--shadow); }
645	.broker-card__logo {
646	  width: 56px; height: 56px; border-radius: var(--radius);
647	  background: var(--bg-secondary); display: flex;
648	  align-items: center; justify-content: center;
649	  font-weight: 800; font-size: 0.8rem; color: var(--accent);
650	  border: 1px solid var(--border);
651	}
652	.broker-card__info { min-width: 0; }
653	.broker-card__name { font-size: 1rem; font-weight: 700; color: #fff; }
654	.broker-card__meta {
655	  display: flex; align-items: center; gap: 10px;
656	  margin-top: 6px; flex-wrap: wrap;
657	}
658	.broker-card__rating {
659	  display: flex; align-items: center; gap: 4px;
660	  font-size: 0.85rem; font-weight: 600;
661	}
662	.broker-card__stat {
663	  font-size: 0.8rem; color: var(--text-secondary);
664	}
665	.broker-card__promo {
666	  font-size: 0.8rem; color: var(--green); font-weight: 500;
667	  margin-top: 6px;
668	}
669	.broker-card__action { text-align: right; white-space: nowrap; }
670	.broker-card__cta {
671	  padding: 10px 24px; background: var(--accent); color: #fff;
672	  border-radius: var(--radius); font-weight: 600; font-size: 0.85rem;
673	  transition: background 0.15s; border: none; cursor: pointer;
674	}
675	.broker-card__cta:hover { background: var(--accent-hover); }
676	
677	.stats-banner {
678	  background: var(--bg-secondary); border: 1px solid var(--border);
679	  border-radius: var(--radius-lg); padding: 40px;
680	  display: flex; justify-content: center; gap: 80px;
681	  margin-top: 32px; text-align: center;
682	}
683	.stats-banner__item {}
684	.stats-banner__value { font-size: 2.4rem; font-weight: 800; color: #fff; }
685	.stats-banner__label { font-size: 0.85rem; color: var(--text-secondary); margin-top: 4px; }
686	
687	/* ─── Pre-market badge ─── */
688	.pre-market {
689	  display: flex; align-items: center; gap: 6px;
690	  padding: 8px 16px; background: var(--bg-card);
691	  border-radius: var(--radius); margin-top: 8px;
692	}
693	.pre-market__label { font-size: 0.7rem; font-weight: 600; color: var(--yellow); text-transform: uppercase; }
694	.pre-market__price { font-size: 0.85rem; font-weight: 600; color: var(--green); }
695	
696	/* ─── Accordion ─── */
697	.accordion-header {
698	  display: flex; align-items: center; justify-content: space-between;
699	  padding: 10px 0; cursor: pointer; user-select: none;
700	}
701	.accordion-header .arrow { transition: transform 0.2s; font-size: 0.7rem; }
702	.accordion-header.collapsed .arrow { transform: rotate(-90deg); }
703	.accordion-body { overflow: hidden; transition: max-height 0.3s; }
704	.accordion-body.collapsed { max-height: 0 !important; }
705	
706	/* ─── Responsive ─── */
707	@media (max-width: 1200px) {
708	  .chart-workspace { grid-template-columns: 200px 1fr 280px; }
709	}
710	@media (max-width: 1024px) {
711	  .chart-workspace {
712	    grid-template-columns: 1fr;
713	    grid-template-rows: auto 1fr auto;
714	    height: auto;
715	  }
716	  .chart-area { min-height: 400px; }
717	  .watchlist { border-right: none; border-bottom: 1px solid var(--border); max-height: 200px; }
718	  .detail-panel { border-left: none; border-top: 1px solid var(--border); }
719	  .footer__grid { grid-template-columns: repeat(3, 1fr); }
720	  .grid--4 { grid-template-columns: repeat(2, 1fr); }
721	  .broker-card { grid-template-columns: 1fr; }
722	  .broker-card__action { text-align: left; }
723	}
724	@media (max-width: 768px) {
725	  .hero h1 { font-size: 2rem; }
726	  .hero p { font-size: 1rem; }
727	  .nav__links { display: none; }
728	  .footer__grid { grid-template-columns: repeat(2, 1fr); }
729	  .grid--3, .grid--2 { grid-template-columns: 1fr; }
730	  .movers-grid { grid-template-columns: 1fr; }
731	  .stats-banner { flex-direction: column; gap: 24px; }
732	  .chart-workspace { grid-template-columns: 1fr; }
733	  .ideas-grid { grid-template-columns: 1fr; }
734	}
735	@media (max-width: 480px) {
736	  .footer__grid { grid-template-columns: 1fr; }
737	  .hero h1 { font-size: 1.6rem; }
738	  .trending-grid { grid-template-columns: repeat(2, 1fr); }
739	}
740	
741	/* ─── Utility ─── */
742	.text-positive { color: var(--green) !important; }
743	.text-negative { color: var(--red) !important; }
744	.text-muted { color: var(--text-muted) !important; }
745	.text-accent { color: var(--accent) !important; }
746	.text-right { text-align: right; }
747	.text-center { text-align: center; }
748	.font-bold { font-weight: 700; }
749	.mt-0 { margin-top: 0; }
750	.mb-8 { margin-bottom: 8px; }
751	.mb-16 { margin-bottom: 16px; }
752	.mb-24 { margin-bottom: 24px; }
753	.gap-8 { gap: 8px; }
754	.gap-16 { gap: 16px; }
755	.flex { display: flex; }
756	.flex-col { flex-direction: column; }
757	.items-center { align-items: center; }
758	.justify-between { justify-content: space-between; }
759	.flex-wrap { flex-wrap: wrap; }
760	.hidden { display: none !important; }
761	
762	/* Tab content switching */
763	.tab-content { display: none; }
764	.tab-content.active { display: block; }
765	
766	/* Scrollbar */
767	::-webkit-scrollbar { width: 6px; height: 6px; }
768	::-webkit-scrollbar-track { background: var(--bg-primary); }
769	::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
770	::-webkit-scrollbar-thumb:hover { background: var(--border-light); }
