file.content:
.detail-panel__stat-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 1px; padding: 0 16px;
}
.detail-panel__stat {
  padding: 10px 0; border-bottom: 1px solid var(--border);
}
.detail-panel__stat-label {
  font-size: 0.7rem; color: var(--text-muted); text-transform: uppercase;
  letter-spacing: 0.3px; margin-bottom: 2px;
}
.detail-panel__stat-value { font-size: 0.85rem; font-weight: 600; color: var(--text-primary); }
.detail-panel__section {
  padding: 14px 16px; border-bottom: 1px solid var(--border);
}
.detail-panel__section-title {
  font-size: 0.8rem; font-weight: 700; color: #fff;
  margin-bottom: 10px;
}
.detail-panel__headline {
  font-size: 0.8rem; color: var(--text-secondary);
  line-height: 1.5; padding: 10px 16px;
  border-bottom: 1px solid var(--border);
}
.financial-row {
  display: flex; justify-content: space-between; align-items: center;
  padding: 6px 0; font-size: 0.8rem;
}
.financial-row__label { color: var(--text-secondary); }
.financial-row__value { font-weight: 600; color: var(--text-primary); }
.financial-row__value.positive { color: var(--green); }
.financial-row__value.negative { color: var(--red); }

/* Detail panel tabs */
.detail-tabs {
  display: flex; border-bottom: 1px solid var(--border);
}
.detail-tab {
  flex: 1; padding: 10px; text-align: center;
  font-size: 0.78rem; font-weight: 600; color: var(--text-secondary);
  border-bottom: 2px solid transparent; transition: all 0.15s;
}
.detail-tab:hover { color: var(--text-primary); }
.detail-tab.active { color: var(--accent); border-bottom-color: var(--accent); }

/* ═══════════════════════════════════════════
   IDEAS PAGE
   ═══════════════════════════════════════════ */
.ideas-header {
  padding: 32px 0 16px;
}
.ideas-header h1 {
  font-size: 1.8rem; font-weight: 800; color: #fff; margin-bottom: 8px;
}
.ideas-header p { color: var(--text-secondary); font-size: 1rem; }
.ideas-filters {
  display: flex; align-items: center; gap: 16px;
  padding: 16px 0; flex-wrap: wrap;
}
.filter-toggle {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 14px; border-radius: 20px;
  background: var(--bg-card); border: 1px solid var(--border);
  font-size: 0.8rem; color: var(--text-secondary);
  transition: all 0.15s; cursor: pointer;
}
.filter-toggle:hover { border-color: var(--accent); color: var(--accent); }
.filter-toggle.active { background: var(--accent-light); border-color: var(--accent); color: var(--accent); }
.filter-toggle__check {
  width: 16px; height: 16px; border-radius: 3px;
  border: 1.5px solid var(--text-muted); display: flex;
  align-items: center; justify-content: center;
  font-size: 0.65rem; transition: all 0.15s;
}
.filter-toggle.active .filter-toggle__check {
  background: var(--accent); border-color: var(--accent); color: #fff;
}
.ideas-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px;
}
.pagination {
  display: flex; justify-content: center; gap: 6px;
  padding: 32px 0;
}
.pagination__btn {
  padding: 8px 14px; border-radius: var(--radius);
  font-size: 0.85rem; font-weight: 500;
  color: var(--text-secondary); border: 1px solid var(--border);
  transition: all 0.15s;
}
.pagination__btn:hover { border-color: var(--accent); color: var(--accent); }
.pagination__btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }

/* ═══════════════════════════════════════════
   MARKETS PAGE
   ═══════════════════════════════════════════ */
.markets-tabs {
  display: flex; gap: 4px; padding: 16px 0;
  overflow-x: auto; scrollbar-width: none;
}
.markets-tabs::-webkit-scrollbar { display: none; }
.markets-tab {
  padding: 10px 20px; border-radius: var(--radius);
  font-size: 0.9rem; font-weight: 600;
  color: var(--text-secondary); background: var(--bg-card);
  transition: all 0.15s; white-space: nowrap; cursor: pointer;
}
.markets-tab:hover { color: var(--text-primary); }
.markets-tab.active { background: var(--accent); color: #fff; }

.market-section { padding: 24px 0; }
.market-section__header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 16px;
}
.market-section__title {
  font-size: 1.2rem; font-weight: 700; color: #fff;
}
.market-section__controls {
  display: flex; gap: 2px;
}
.chart-option {
  padding: 4px 10px; font-size: 0.75rem; font-weight: 500;
  color: var(--text-muted); border-radius: 3px; transition: all 0.1s;
}
.chart-option:hover { color: var(--text-secondary); }
.chart-option.active { color: var(--accent); background: var(--accent-light); }

.mini-chart { width: 100%; height: 40px; }

.movers-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
}
.mover-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 16px;
}
.mover-card__title {
  font-size: 0.85rem; font-weight: 700; color: #fff; margin-bottom: 12px;
}
.mover-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 0; border-bottom: 1px solid var(--border);
}
.mover-item:last-child { border-bottom: none; }
.mover-item__name { font-size: 0.85rem; color: var(--text-primary); }
.mover-item__change { font-weight: 700; font-size: 0.85rem; }
.mover-item__change.positive { color: var(--green); }
.mover-item__change.negative { color: var(--red); }

.earnings-table-wrap { overflow-x: auto; }

/* ═══════════════════════════════════════════
   BROKERS PAGE
   ═══════════════════════════════════════════ */
.brokers-hero {
  padding: 60px 0 40px; text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.brokers-hero h1 { font-size: 2.2rem; font-weight: 800; color: #fff; margin-bottom: 8px; }
.brokers-hero p { color: var(--text-secondary); font-size: 1.05rem; max-width: 520px; margin: 0 auto; }

.broker-filters {
  display: flex; align-items: center; gap: 16px;
  padding: 20px 0; flex-wrap: wrap;
}
.broker-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  display: grid; grid-template-columns: auto 1fr auto;
  gap: 20px; align-items: center;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.broker-card:hover { border-color: var(--border-light); box-shadow: var(--shadow); }
.broker-card__logo {
  width: 56px; height: 56px; border-radius: var(--radius);
  background: var(--bg-secondary); display: flex;
  align-items: center; justify-content: center;
  font-weight: 800; font-size: 0.8rem; color: var(--accent);
  border: 1px solid var(--border);
}
.broker-card__info { min-width: 0; }
.broker-card__name { font-size: 1rem; font-weight: 700; color: #fff; }
.broker-card__meta {
  display: flex; align-items: center; gap: 10px;
  margin-top: 6px; flex-wrap: wrap;
}
.broker-card__rating {
  display: flex; align-items: center; gap: 4px;
  font-size: 0.85rem; font-weight: 600;
}
.broker-card__stat {
  font-size: 0.8rem; color: var(--text-secondary);
}
.broker-card__promo {
  font-size: 0.8rem; color: var(--green); font-weight: 500;
  margin-top: 6px;
}
.broker-card__action { text-align: right; white-space: nowrap; }
.broker-card__cta {
  padding: 10px 24px; background: var(--accent); color: #fff;
  border-radius: var(--radius); font-weight: 600; font-size: 0.85rem;
  transition: background 0.15s; border: none; cursor: pointer;
}
.broker-card__cta:hover { background: var(--accent-hover); }

.stats-banner {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 40px;
  display: flex; justify-content: center; gap: 80px;
  margin-top: 32px; text-align: center;
}
.stats-banner__item {}
.stats-banner__value { font-size: 2.4rem; font-weight: 800; color: #fff; }
.stats-banner__label { font-size: 0.85rem; color: var(--text-secondary); margin-top: 4px; }

/* ─── Pre-market badge ─── */
.pre-market {
  display: flex; align-items: center; gap: 6px;
  padding: 8px 16px; background: var(--bg-card);
  border-radius: var(--radius); margin-top: 8px;
}
.pre-market__label { font-size: 0.7rem; font-weight: 600; color: var(--yellow); text-transform: uppercase; }
.pre-market__price { font-size: 0.85rem; font-weight: 600; color: var(--green); }

/* ─── Accordion ─── */
.accordion-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 0; cursor: pointer; user-select: none;
}
.accordion-header .arrow { transition: transform 0.2s; font-size: 0.7rem; }
.accordion-header.collapsed .arrow { transform: rotate(-90deg); }
.accordion-body { overflow: hidden; transition: max-height 0.3s; }
.accordion-body.collapsed { max-height: 0 !important; }

/* ─── Responsive ─── */
@media (max-width: 1200px) {
  .chart-workspace { grid-template-columns: 200px 1fr 280px; }
}
@media (max-width: 1024px) {
  .chart-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    height: auto;
  }
  .chart-area { min-height: 400px; }
  .watchlist { border-right: none; border-bottom: 1px solid var(--border); max-height: 200px; }
  .detail-panel { border-left: none; border-top: 1px solid var(--border); }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .grid--4 { grid-template-columns: repeat(2, 1fr); }
  .broker-card { grid-template-columns: 1fr; }
  .broker-card__action { text-align: left; }
}
@media (max-width: 768px) {
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .nav__links { display: none; }
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .grid--3, .grid--2 { grid-template-columns: 1fr; }
  .movers-grid { grid-template-columns: 1fr; }
  .stats-banner { flex-direction: column; gap: 24px; }
  .chart-workspace { grid-template-columns: 1fr; }
  .ideas-grid { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .footer__grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 1.6rem; }
  .trending-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ─── Utility ─── */
.text-positive { color: var(--green) !important; }
.text-negative { color: var(--red) !important; }
.text-muted { color: var(--text-muted) !important; }
.text-accent { color: var(--accent) !important; }
.text-right { text-align: right; }
.text-center { text-align: center; }
.font-bold { font-weight: 700; }
.mt-0 { margin-top: 0; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.gap-8 { gap: 8px; }
.gap-16 { gap: 16px; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.flex-wrap { flex-wrap: wrap; }
.hidden { display: none !important; }

/* Tab content switching */
.tab-content { display: none; }
.tab-content.active { display: block; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--border-light); }

